const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define location: Mekong River at (20.248364, 100.141422)
  const point = ee.Geometry.Point([100.141422, 20.248364]);
  const buffer = point.buffer(500); // 500m buffer for analysis

  // Define date ranges (±3 days to capture available imagery)
  const date1_start = '2015-01-24';
  const date1_end = '2015-01-30';
  const date2_start = '2020-01-22';
  const date2_end = '2020-01-28';

  // Function to calculate NDTI (Normalized Difference Turbidity Index)
  function calculateNDTI(img) {
    const ndti = img.normalizedDifference(['B4', 'B11']).rename('NDTI');
    return img.addBands(ndti);
  }

  // Function to mask clouds using QA60
  function maskClouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask);
  }

  // Acquire Sentinel-2 data for 2015
  let col2015 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(buffer)
    .filterDate(date1_start, date1_end)
    .map(maskClouds)
    .map(calculateNDTI);

  const size2015 = col2015.size().getInfo();
  console.log(`2015 Images: ${size2015}`);

  if (size2015 === 0) {
    console.log('No images found for 2015, trying Landsat 8');
    col2015 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(date1_start, date1_end)
      .select(['SR_B4', 'SR_B6'])
      .filterMetadata('CLOUD_COVER', 'less_than', 50);
    const sizeL82015 = col2015.size().getInfo();
    console.log(`Landsat 8 2015: ${sizeL82015}`);
    if (sizeL82015 === 0) {
      console.log('No valid data for 2015');
      console.log('C1');
      return;
    }
  }

  // Acquire Sentinel-2 data for 2020
  let col2020 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(buffer)
    .filterDate(date2_start, date2_end)
    .map(maskClouds)
    .map(calculateNDTI);

  const size2020 = col2020.size().getInfo();
  console.log(`2020 Images: ${size2020}`);

  if (size2020 === 0) {
    console.log('No images found for 2020, trying Landsat 8');
    col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(date2_start, date2_end)
      .select(['SR_B4', 'SR_B6'])
      .filterMetadata('CLOUD_COVER', 'less_than', 50);
    const sizeL82020 = col2020.size().getInfo();
    console.log(`Landsat 8 2020: ${sizeL82020}`);
    if (sizeL82020 === 0) {
      console.log('No valid data for 2020');
      console.log('C1');
      return;
    }
  }

  // Calculate median NDTI for 2015
  const median2015 = col2015.select('NDTI').median();
  const count2015 = median2015.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  console.log(`2015 Valid pixels: ${count2015}`);

  if (count2015 === 0) {
    console.log('No valid pixels for 2015 after masking');
    console.log('C2');
    return;
  }

  const ndti2015 = median2015.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  // Calculate median NDTI for 2020
  const median2020 = col2020.select('NDTI').median();
  const count2020 = median2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  console.log(`2020 Valid pixels: ${count2020}`);

  if (count2020 === 0) {
    console.log('No valid pixels for 2020 after masking');
    console.log('C2');
    return;
  }

  const ndti2020 = median2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  console.log(`NDTI 2015: ${ndti2015}`);
  console.log(`NDTI 2020: ${ndti2020}`);

  // Validation
  if (ndti2015 === null || isNaN(ndti2015) || ndti2020 === null || isNaN(ndti2020)) {
    console.log('Calculation resulted in invalid values');
    console.log('C3');
    return;
  }

  // Compare
  if (ndti2015 > ndti2020) {
    console.log('More sediment in 2015 than 2020');
    console.log('A');
  } else {
    console.log('More sediment in 2020 than 2015 or equal');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
